def Rlnm(l, n, m, k, z, N_t):
    """Function to calculate the translation coefficient (R|R)lmn.
    Input
    l : int
        The principal quantum number for the expansion.
    n : int
        The principal quantum number for the reexpansion.
    m : int
        The magnetic quantum number for the reexpansion.
    k : float
        Wavevector of the optical beam.
    z : float
        The translation distance along z direction
    N_t : int
        Truncated space size.
    Output
    (R|R)lmn : complex
        The translation coefficient (R|R)lmn.
    """
    kr = k * z

    def a_nm(n_idx, m_idx):
        """Calculate coefficient a_n^m"""
        abs_m = abs(m_idx)
        if n_idx < abs_m:
            return 0.0
        return np.sqrt((n_idx + 1 + abs_m) * (n_idx + 1 - abs_m) / ((2 * n_idx + 1) * (2 * n_idx + 3)))

    def b_nm(n_idx, m_idx):
        """Calculate coefficient b_n^m"""
        abs_m = abs(m_idx)
        if n_idx < abs_m:
            return 0.0
        if m_idx >= 0:
            return np.sqrt((n_idx - m_idx - 1) * (n_idx - m_idx) / ((2 * n_idx - 1) * (2 * n_idx + 1)))
        else:
            return -np.sqrt((n_idx - m_idx - 1) * (n_idx - m_idx) / ((2 * n_idx - 1) * (2 * n_idx + 1)))
    coeff = {}
    for l_idx in range(N_t + 1):
        jl = scipy.special.spherical_jn(l_idx, kr)
        coeff[l_idx, 0, 0] = (-1) ** l_idx * np.sqrt(2 * l_idx + 1) * jl
    for m_idx in range(N_t):
        for l_idx in range(m_idx + 1, N_t + 1):
            b_coeff = b_nm(m_idx + 1, -(m_idx + 1))
            if abs(b_coeff) > 1e-15:
                b_left = b_nm(l_idx - 1, -m_idx)
                b_right = b_nm(l_idx + 1, m_idx)
                val_left = coeff.get((l_idx - 1, m_idx, m_idx), 0.0)
                val_right = coeff.get((l_idx + 1, m_idx, m_idx), 0.0)
                coeff[l_idx, m_idx + 1, m_idx + 1] = (b_left * val_left - b_right * val_right) / b_coeff
    for m_idx in range(N_t + 1):
        for n_idx in range(m_idx, N_t + 1):
            for l_idx in range(N_t + 1):
                if n_idx == m_idx:
                    continue
                a_coeff_left = a_nm(n_idx - 1, m_idx)
                a_coeff_right = a_nm(n_idx, m_idx)
                if abs(a_coeff_right) > 1e-15:
                    a_coeff_l_right = a_nm(l_idx, m_idx)
                    a_coeff_l_left = a_nm(l_idx - 1, m_idx)
                    val_left = coeff.get((l_idx, n_idx - 1, m_idx), 0.0)
                    val_right_l = coeff.get((l_idx + 1, n_idx, m_idx), 0.0)
                    val_l_left = coeff.get((l_idx + 1, n_idx, m_idx), 0.0)
                    val_l_right = coeff.get((l_idx - 1, n_idx, m_idx), 0.0)
                    coeff[l_idx, n_idx, m_idx] = (a_coeff_left * val_left + a_coeff_l_right * val_l_left - a_coeff_l_left * val_l_right) / a_coeff_right
    return coeff.get((l, n, m), 0.0 + 0j)

def Tnvm(n, v, m, Q):
    """Function to calculate the rotation coefficient Tnvm.
    Input
    n : int
        The principal quantum number for both expansion and reexpansion.
    m : int
        The magnetic quantum number for the reexpansion.
    v : int
        The magnetic quantum number for the expansion.
    Q : matrix of shape(3, 3)
        The rotation matrix.
    Output
    T : complex
        The rotation coefficient Tnvm.
    """

    def a_nm(n_idx, m_idx):
        """Calculate coefficient a_n^m"""
        abs_m = abs(m_idx)
        if n_idx < abs_m:
            return 0.0
        return np.sqrt((n_idx + 1 + abs_m) * (n_idx + 1 - abs_m) / ((2 * n_idx + 1) * (2 * n_idx + 3)))

    def b_nm(n_idx, m_idx):
        """Calculate coefficient b_n^m"""
        abs_m = abs(m_idx)
        if n_idx < abs_m:
            return 0.0
        if m_idx >= 0:
            return np.sqrt((n_idx - m_idx - 1) * (n_idx - m_idx) / ((2 * n_idx - 1) * (2 * n_idx + 1)))
        else:
            return -np.sqrt((n_idx - m_idx - 1) * (n_idx - m_idx) / ((2 * n_idx - 1) * (2 * n_idx + 1)))

    def spherical_harmonic(n_idx, m_idx, theta, phi):
        """Calculate spherical harmonic Y_n^m(theta, phi)"""
        if np.sin(theta) < 1e-15:
            if abs(m_idx) > 1e-15:
                return 0.0
            if theta < np.pi / 2:
                return np.sqrt((2 * n_idx + 1) / (4 * np.pi)) if m_idx == 0 else 0.0
            else:
                return np.sqrt((2 * n_idx + 1) / (4 * np.pi)) * (-1) ** n_idx if m_idx == 0 else 0.0
        leg = scipy.special.lpmv(m_idx, n_idx, np.cos(theta))
        norm = np.sqrt((2 * n_idx + 1) / (4 * np.pi) * scipy.special.factorial(n_idx - abs(m_idx)) / scipy.special.factorial(n_idx + abs(m_idx)))
        Y = norm * leg * np.exp(1j * m_idx * phi)
        return Y
    Q11, Q12, Q13 = (Q[0, 0], Q[0, 1], Q[0, 2])
    Q21, Q22, Q23 = (Q[1, 0], Q[1, 1], Q[1, 2])
    Q31, Q32, Q33 = (Q[2, 0], Q[2, 1], Q[2, 2])
    z_rot = np.array([Q31, Q32, Q33])
    r_norm = np.linalg.norm(z_rot)
    if r_norm < 1e-15:
        theta_prime = 0.0
        phi_prime = 0.0
    else:
        z_rot_normalized = z_rot / r_norm
        theta_prime = np.arccos(np.clip(z_rot_normalized[2], -1.0, 1.0))
        phi_prime = np.arctan2(z_rot_normalized[1], z_rot_normalized[0])
    T_coeff = {}
    for nu_idx in range(-n, n + 1):
        Y_val = spherical_harmonic(n, -nu_idx, theta_prime, phi_prime)
        T_coeff[nu_idx, 0] = np.sqrt(4 * np.pi / (2 * n + 1)) * Y_val
    for m_idx in range(n + 1):
        for nu_idx in range(-n, n + 1):
            if m_idx == 0:
                continue
            b_coeff = b_nm(n, -m_idx)
            if abs(b_coeff) > 1e-15:
                b_left = b_nm(n, -(nu_idx - 1))
                b_right = b_nm(n, nu_idx + 1)
                val_nu_minus = T_coeff.get((nu_idx - 1, m_idx - 1), 0.0)
                val_nu_plus = T_coeff.get((nu_idx + 1, m_idx - 1), 0.0)
                val_nu = T_coeff.get((nu_idx, m_idx - 1), 0.0)
                a_coeff = a_nm(n, nu_idx)
                term1 = (Q11 + Q22 + 1j * (Q12 - Q21)) * b_left * val_nu_minus
                term2 = (Q11 - Q22 + 1j * (Q12 + Q21)) * b_right * val_nu_plus
                term3 = 2 * (Q31 + 1j * Q32) * a_coeff * val_nu
                T_coeff[nu_idx, m_idx] = (term1 + term2 - term3) / (2 * b_coeff)
            else:
                T_coeff[nu_idx, m_idx] = 0.0
    return T_coeff.get((v, m), 0.0 + 0j)

